-- Authorization helpers must exist before policies reference them.
create or replace function public.is_org_admin(org uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.role_memberships where user_id = auth.uid() and organization_id = org and role = 'admin' and is_active) $$;
create or replace function public.has_role(target public.app_role) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.role_memberships where user_id = auth.uid() and role = target and is_active) $$;
create or replace function public.teacher_has_class(target_class uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.teacher_class_assignments where teacher_user_id = auth.uid() and class_id = target_class and is_active) $$;
create or replace function public.parent_has_student(target_student uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.parent_student_relationships where parent_user_id = auth.uid() and student_id = target_student and is_active) $$;

-- Every browser-facing table has RLS enabled. Service-role scripts bypass RLS only on the server.
alter table public.organizations enable row level security; alter table public.schools enable row level security; alter table public.profiles enable row level security; alter table public.role_memberships enable row level security; alter table public.classes enable row level security; alter table public.students enable row level security; alter table public.parent_student_relationships enable row level security; alter table public.teacher_class_assignments enable row level security; alter table public.stores enable row level security; alter table public.store_memberships enable row level security; alter table public.student_qr_credentials enable row level security; alter table public.store_checkin_codes enable row level security; alter table public.missions enable row level security; alter table public.mission_versions enable row level security; alter table public.mission_stages enable row level security; alter table public.mission_questions enable row level security; alter table public.mission_answer_options enable row level security; alter table public.mission_assignments enable row level security; alter table public.mission_attempts enable row level security; alter table public.mission_responses enable row level security; alter table public.reading_recordings enable row level security; alter table public.products enable row level security; alter table public.reward_goals enable row level security; alter table public.reward_events enable row level security; alter table public.notifications enable row level security; alter table public.notification_preferences enable row level security; alter table public.mission_favorites enable row level security; alter table public.mission_ratings enable row level security; alter table public.mission_flags enable row level security; alter table public.sync_events enable row level security; alter table public.audit_logs enable row level security;

create policy "members view organization" on public.organizations for select using (exists(select 1 from public.role_memberships rm where rm.organization_id=id and rm.user_id=auth.uid() and rm.is_active));
create policy "admins manage organizations" on public.organizations for all using (public.is_org_admin(id)) with check (public.is_org_admin(id));
create policy "members view schools" on public.schools for select using (exists(select 1 from public.role_memberships rm where rm.organization_id=schools.organization_id and rm.user_id=auth.uid() and rm.is_active));
create policy "admins manage schools" on public.schools for all using (public.is_org_admin(organization_id)) with check (public.is_org_admin(organization_id));
create policy "users view own profile" on public.profiles for select using (id=auth.uid() or exists(select 1 from public.role_memberships rm where rm.user_id=auth.uid() and rm.role='admin' and rm.is_active));
create policy "users update own profile" on public.profiles for update using (id=auth.uid()) with check (id=auth.uid());
create policy "users view own memberships" on public.role_memberships for select using (user_id=auth.uid() or public.is_org_admin(organization_id));
create policy "admins manage memberships" on public.role_memberships for all using (public.is_org_admin(organization_id)) with check (public.is_org_admin(organization_id));
create policy "authorized class view" on public.classes for select using (public.is_org_admin((select organization_id from public.schools where id=school_id)) or public.teacher_has_class(id) or exists(select 1 from public.students s join public.parent_student_relationships psr on psr.student_id=s.id where s.class_id=classes.id and psr.parent_user_id=auth.uid() and psr.is_active));
create policy "admins manage classes" on public.classes for all using (public.is_org_admin((select organization_id from public.schools where id=school_id))) with check (public.is_org_admin((select organization_id from public.schools where id=school_id)));
create policy "teachers manage assigned class memberships" on public.classes for update using (public.teacher_has_class(id)) with check (public.teacher_has_class(id));
create policy "authorized student view" on public.students for select using (public.is_org_admin(organization_id) or public.parent_has_student(id) or (class_id is not null and public.teacher_has_class(class_id)));
create policy "admins manage students" on public.students for all using (public.is_org_admin(organization_id)) with check (public.is_org_admin(organization_id));
create policy "teachers manage assigned students" on public.students for update using (class_id is not null and public.teacher_has_class(class_id)) with check (class_id is not null and public.teacher_has_class(class_id));
create policy "parents view own links" on public.parent_student_relationships for select using (parent_user_id=auth.uid() or public.is_org_admin((select organization_id from public.students where id=student_id)));
create policy "admins manage parent links" on public.parent_student_relationships for all using (public.is_org_admin((select organization_id from public.students where id=student_id))) with check (public.is_org_admin((select organization_id from public.students where id=student_id)));
create policy "teachers view own assignments" on public.teacher_class_assignments for select using (teacher_user_id=auth.uid() or public.is_org_admin((select s.organization_id from public.classes c join public.schools s on s.id=c.school_id where c.id=class_id)));
create policy "admins manage teacher assignments" on public.teacher_class_assignments for all using (public.is_org_admin((select s.organization_id from public.classes c join public.schools s on s.id=c.school_id where c.id=class_id))) with check (public.is_org_admin((select s.organization_id from public.classes c join public.schools s on s.id=c.school_id where c.id=class_id)));
create policy "authorized stores view store" on public.stores for select using (public.is_org_admin(organization_id) or exists(select 1 from public.store_memberships sm where sm.store_id=id and sm.user_id=auth.uid() and sm.is_active));
create policy "admins manage stores" on public.stores for all using (public.is_org_admin(organization_id)) with check (public.is_org_admin(organization_id));
create policy "users view own store memberships" on public.store_memberships for select using (user_id=auth.uid() or public.is_org_admin((select organization_id from public.stores where id=store_id)));
create policy "admins manage store memberships" on public.store_memberships for all using (public.is_org_admin((select organization_id from public.stores where id=store_id))) with check (public.is_org_admin((select organization_id from public.stores where id=store_id)));
create policy "staff manage student qr" on public.student_qr_credentials for all using (public.is_org_admin((select organization_id from public.students where id=student_id)) or public.teacher_has_class((select class_id from public.students where id=student_id))) with check (public.is_org_admin((select organization_id from public.students where id=student_id)) or public.teacher_has_class((select class_id from public.students where id=student_id)));
create policy "store users view codes" on public.store_checkin_codes for select using (exists(select 1 from public.store_memberships sm where sm.store_id=store_id and sm.user_id=auth.uid() and sm.is_active) or public.is_org_admin((select organization_id from public.stores where id=store_id)));
create policy "admins manage checkin codes" on public.store_checkin_codes for all using (public.is_org_admin((select organization_id from public.stores where id=store_id))) with check (public.is_org_admin((select organization_id from public.stores where id=store_id)));
create policy "shared or authorized missions view" on public.missions for select using (sharing_status in ('approved','featured') or creator_user_id=auth.uid() or public.is_org_admin(organization_id));
create policy "teachers create missions" on public.missions for insert with check (creator_user_id=auth.uid() and public.has_role('teacher'));
create policy "creator or admin updates missions" on public.missions for update using (creator_user_id=auth.uid() or public.is_org_admin(organization_id)) with check (creator_user_id=auth.uid() or public.is_org_admin(organization_id));
create policy "mission details inherit visibility" on public.mission_versions for select using (exists(select 1 from public.missions m where m.id=mission_id and (m.sharing_status in ('approved','featured') or m.creator_user_id=auth.uid() or public.is_org_admin(m.organization_id))));
create policy "mission stages inherit visibility" on public.mission_stages for select using (exists(select 1 from public.mission_versions v join public.missions m on m.id=v.mission_id where v.id=mission_version_id and (m.sharing_status in ('approved','featured') or m.creator_user_id=auth.uid() or public.is_org_admin(m.organization_id))));
create policy "questions inherit visibility" on public.mission_questions for select using (exists(select 1 from public.mission_stages s join public.mission_versions v on v.id=s.mission_version_id join public.missions m on m.id=v.mission_id where s.id=stage_id and (m.sharing_status in ('approved','featured') or m.creator_user_id=auth.uid() or public.is_org_admin(m.organization_id))));
create policy "options inherit visibility" on public.mission_answer_options for select using (exists(select 1 from public.mission_questions q join public.mission_stages s on s.id=q.stage_id join public.mission_versions v on v.id=s.mission_version_id join public.missions m on m.id=v.mission_id where q.id=question_id and (m.sharing_status in ('approved','featured') or m.creator_user_id=auth.uid() or public.is_org_admin(m.organization_id))));
create policy "authorized assignments view" on public.mission_assignments for select using (public.teacher_has_class(class_id) or public.is_org_admin((select s.organization_id from public.classes c join public.schools s on s.id=c.school_id where c.id=class_id)) or exists(select 1 from public.students st where st.class_id=mission_assignments.class_id and public.parent_has_student(st.id)));
create policy "teachers assign to own class" on public.mission_assignments for insert with check (assigned_by=auth.uid() and public.teacher_has_class(class_id));
create policy "authorized attempts view" on public.mission_attempts for select using (public.parent_has_student(student_id) or public.is_org_admin((select organization_id from public.students where id=student_id)) or public.teacher_has_class((select class_id from public.students where id=student_id)));
create policy "authorized responses view" on public.mission_responses for select using (exists(select 1 from public.mission_attempts a where a.id=attempt_id and (public.parent_has_student(a.student_id) or public.teacher_has_class((select class_id from public.students where id=a.student_id)) or public.is_org_admin((select organization_id from public.students where id=a.student_id)))));
create policy "authorized recordings view" on public.reading_recordings for select using (public.parent_has_student(student_id) or public.teacher_has_class((select class_id from public.students where id=student_id)) or public.is_org_admin((select organization_id from public.students where id=student_id)));
create policy "teachers review recordings" on public.reading_recordings for update using (public.teacher_has_class((select class_id from public.students where id=student_id)) or public.is_org_admin((select organization_id from public.students where id=student_id))) with check (public.teacher_has_class((select class_id from public.students where id=student_id)) or public.is_org_admin((select organization_id from public.students where id=student_id)));
create policy "members view products" on public.products for select using (public.has_role('teacher') or public.has_role('admin'));
create policy "admins manage products" on public.products for all using (public.has_role('admin')) with check (public.has_role('admin'));
create policy "authorized rewards view" on public.reward_goals for select using (public.is_org_admin((select organization_id from public.stores where id=store_id)) or public.teacher_has_class(class_id) or exists(select 1 from public.store_memberships sm where sm.store_id=reward_goals.store_id and sm.user_id=auth.uid() and sm.is_active) or exists(select 1 from public.students st where st.class_id=reward_goals.class_id and public.parent_has_student(st.id)));
create policy "staff manage rewards" on public.reward_goals for all using (public.is_org_admin((select s.organization_id from public.classes c join public.schools s on s.id=c.school_id where c.id=class_id)) or public.teacher_has_class(class_id)) with check (public.is_org_admin((select s.organization_id from public.classes c join public.schools s on s.id=c.school_id where c.id=class_id)) or public.teacher_has_class(class_id));
create policy "users view own notifications" on public.notifications for select using (recipient_user_id=auth.uid());
create policy "users update own notifications" on public.notifications for update using (recipient_user_id=auth.uid()) with check (recipient_user_id=auth.uid());
create policy "users manage own notification preferences" on public.notification_preferences for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "users manage own favorites" on public.mission_favorites for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "users manage own ratings" on public.mission_ratings for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "users create flags" on public.mission_flags for insert with check (reporter_user_id=auth.uid());
create policy "admins view flags" on public.mission_flags for select using (exists(select 1 from public.missions m where m.id=mission_id and public.is_org_admin(m.organization_id)));
create policy "admins view audit logs" on public.audit_logs for select using (public.is_org_admin(organization_id));

-- A deliberately aggregate-only view for store participation. It contains no student identifiers or PII.
create view public.store_participation_summary with (security_invoker=true) as select rg.store_id, count(distinct ma.id) as mission_assignments, count(distinct ma.class_id) as participating_classes, count(distinct a.id) filter (where a.status='completed') as completed_attempts from public.reward_goals rg left join public.mission_assignments ma on ma.class_id=rg.class_id left join public.mission_attempts a on a.assignment_id=ma.id group by rg.store_id;
